func TestScanResultKEVs(t *testing.T) {
	r := ScanResult{ScannedCves: VulnInfos{
		"CVE-1": {KEVs: []KEV{
			{Type: VulnCheckKEVType, VulnerabilityName: "Zulu"},
			{Type: CISAKEVType, VulnerabilityName: "Bravo"},
			{Type: VulnCheckKEVType, VulnerabilityName: "Alpha"},
			{Type: CISAKEVType, VulnerabilityName: "Alpha"},
		}},
		"CVE-2": {KEVs: []KEV{{Type: CISAKEVType}}},
		"CVE-3": {AlertDict: AlertDict{CISA: []Alert{{Title: "legacy"}}}},
	}}
	if got := r.FormatKEVCveSummary(); got != "2 KEVs" {
		t.Errorf("KEV summary = %q, want %q", got, "2 KEVs")
	}
	r.SortForJSONOutput()
	got := r.ScannedCves["CVE-1"].KEVs
	want := []KEV{
		{Type: CISAKEVType, VulnerabilityName: "Alpha"},
		{Type: CISAKEVType, VulnerabilityName: "Bravo"},
		{Type: VulnCheckKEVType, VulnerabilityName: "Alpha"},
		{Type: VulnCheckKEVType, VulnerabilityName: "Zulu"},
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("sorted KEVs = %#v, want %#v", got, want)
	}

	data, err := json.Marshal(r.ScannedCves["CVE-1"])
	if err != nil {
		t.Fatal(err)
	}
	var encoded map[string]json.RawMessage
	if err := json.Unmarshal(data, &encoded); err != nil {
		t.Fatal(err)
	}
	if _, ok := encoded["kevs"]; !ok {
		t.Errorf("KEVs missing from vulnerability JSON: %s", data)
	}
}

